import { Link } from "react-router-dom";

import "./Card.css";

function Card() {


  return <div>
    {product.map((elm,i)=>{
      return(
        <div className="box" key={i}>
          <img src={elm.images} alt="product" />
          <div className="description">
          <h2 className="title">{elm.title}</h2>
          <p className="price"> <span> ${(elm.price+1.2).toFixed(2)}</span> ${elm.price}</p>
          <Link to='' className="more">More...</Link>
          </div>
        </div>
      )
    })}
  </div>;
}

export default Card;
